class Solution { public int[] gridIllumination(int n,int[][] lamps,int[][] queries){Set<Long> active=new HashSet<>();Map<Integer,Integer> rows=new HashMap<>(),columns=new HashMap<>(),diagonals=new HashMap<>(),antis=new HashMap<>();for(int[] lamp:lamps)if(active.add(key(lamp[0],lamp[1]))){add(rows,lamp[0],1);add(columns,lamp[1],1);add(diagonals,lamp[0]-lamp[1],1);add(antis,lamp[0]+lamp[1],1);}int[] answer=new int[queries.length];for(int i=0;i<queries.length;i++){int r=queries[i][0],c=queries[i][1];answer[i]=rows.getOrDefault(r,0)>0||columns.getOrDefault(c,0)>0||diagonals.getOrDefault(r-c,0)>0||antis.getOrDefault(r+c,0)>0?1:0;for(int dr=-1;dr<=1;dr++)for(int dc=-1;dc<=1;dc++){int nr=r+dr,nc=c+dc;if(nr>=0&&nr<n&&nc>=0&&nc<n&&active.remove(key(nr,nc))){add(rows,nr,-1);add(columns,nc,-1);add(diagonals,nr-nc,-1);add(antis,nr+nc,-1);}}}return answer;}private long key(int r,int c){return((long)r<<32)^(c&0xffffffffL);}private void add(Map<Integer,Integer> map,int key,int delta){map.put(key,map.getOrDefault(key,0)+delta);} }
